import React, { useState } from 'react';
import { Routes, Route, Link } from 'react-router-dom';
import './App.css';

import Home from './pages/Home';
import News from './pages/News';
import About from './pages/About';
import Contact from './pages/Contact';
import Products from './pages/Products';

import logo from './images/logo.png';

function App() {
  const [lang, setLang] = useState('ru');

  const text = {
    ru: {
      home: 'Главная',
      products: 'Меню',
      news: 'Новости',
      contact: 'Контакты',
      about: 'О нас',
      footer: '📞 +7 908 110 52 67 | 📍 ул. Зорге, 15, Ростов-на-Дону | © 2026 «Coffee Time»',
      tagsTitle: 'Облако тегов',
      bannerLeft: 'Скидка 20%\nна первый заказ',
      bannerRight: 'Свежая выпечка\nкаждый час!',
      langButton: 'EN'
    },
    en: {
      home: 'Home',
      news: 'News',
      about: 'About us',
      contact: 'Contact',
      products: 'Menu',
      footer: '📞 +7 908 517 50 43 | 📍 Arbat St., 15, Moscow | © 2025 "Cozy Corner"',
      tagsTitle: 'Tag cloud',
      bannerLeft: '20% discount\non first order',
      bannerRight: 'Fresh pastries\nevery hour!',
      langButton: 'RU'
    }
  };

  return (
    <div className="app">
      {/* ========== ШАПКА (HEADER) — 3% высоты ========== */}
      <header className="app-header">
        <div className="logo-container">
          <img src={logo} alt="Логотип кофейни" className="logo" />
          <h2 className="logo-text">Уютный уголок</h2>
        </div>
      </header>

      {/* ========== ОСНОВНАЯ ЧАСТЬ (MAIN) — 89% высоты ========== */}
      <main className="app-main">

        {/* ЛЕВЫЙ БЛОК (SECTION) — 20% ширины, цвет soft wheat */}
        <aside className="app-section">
          <h3>Навигация</h3>
          <nav className="main-nav">
            <Link to="/">{text[lang].home}</Link>
            <Link to="/news">{text[lang].news}</Link>
            <Link to="/about">{text[lang].about}</Link>
            <Link to="/contact">{text[lang].contact}</Link>
            <Link to="/products">{text[lang].products}</Link>
          </nav>

          <div className="banner banner-left">
            <p>{text[lang].bannerLeft.split('\n').map((line, i) => (
              <span key={i}>{line}<br /></span>
            ))}</p>
          </div>
        </aside>

        {/* ЦЕНТРАЛЬНЫЙ БЛОК (ARTICLE) — 60% ширины, цвет ivory */}
        <article className="app-article">
          {/* Кнопка переключения языка */}
          <button
            className="lang-switch"
            onClick={() => setLang(lang === 'ru' ? 'en' : 'ru')}
          >
            {text[lang].langButton}
          </button>

          {/* Маршрутизация страниц */}
          <Routes>
            <Route path="/" element={<Home lang={lang} text={text} />} />
            <Route path="/news" element={<News lang={lang} />} />
            <Route path="/about" element={<About lang={lang} />} />
            <Route path="/contact" element={<Contact lang={lang} />} />
            <Route path="/products" element={<Products lang={lang} />} />
          </Routes>
        </article>

        {/* ПРАВЫЙ БЛОК (ASIDE) — 20% ширины, цвет soft wheat */}
        <aside className="app-aside">
          <h3>{text[lang].tagsTitle}</h3>
          <div className="tags">
            <span className="tag">капучино</span>
            <span className="tag">латте</span>
            <span className="tag">эспрессо</span>
            <span className="tag">раф</span>
            <span className="tag">круассан</span>
            <span className="tag">чизкейк</span>
            <span className="tag">сэндвич</span>
            <span className="tag">глясе</span>
          </div>

          <div className="banner banner-right">
            <p>{text[lang].bannerRight.split('\n').map((line, i) => (
              <span key={i}>{line}<br /></span>
            ))}</p>
          </div>
        </aside>
      </main>

      {/* ========== ПОДВАЛ (FOOTER) — 4% высоты ========== */}
      <footer className="app-footer">
        <p>{text[lang].footer}</p>
      </footer>
    </div>
  );
}

export default App;
